// Calcula em que dia/semana do Desafio a noiva está, e monta o contexto pra Rosa
const lead = $input.first().json;
const dataCompra = new Date(lead.data_compra || Date.now());
const hoje = new Date();
const diaAtual = Math.max(1, Math.min(21, Math.floor((hoje - dataCompra) / 86400000) + 1));
const semana = Math.ceil(diaAtual / 7);

const fases = {
  1: "Semana 1 - Choque Anti-Inchaço: foco em hidratação, água morna com limão, treinos leves de ativação e mobilidade.",
  2: "Semana 2 - Intensifica: mais proteína e fibra, treinos em circuito mais intensos.",
  3: "Semana 3 - Reta Final / Prova do Vestido: cardápio leve anti-inchaço, treino de tonificação e alongamento, foco em preparação emocional pro grande dia."
};

return [{
  json: {
    nome: lead.nome || 'noiva',
    telefone: lead.telefone,
    restricoes: lead.restricoes_alimentares || 'nenhuma restrição informada',
    dia_atual: diaAtual,
    semana: semana,
    fase_descricao: fases[semana],
    pergunta: $('Webhook - Mensagem Recebida (Z-API)').first().json.body.text?.message || ''
  }
}];

const resposta = $input.first().json;
const texto = resposta.content && resposta.content[0] ? resposta.content[0].text : 'Desculpa, tive um probleminha aqui — pode repetir? 🌹';
return [{ json: { telefone: $('Calcular Dia/Semana + Contexto').first().json.telefone, resposta_texto: texto } }];
